                  {settings.tuningSystem === 'et' && (
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 animate-in slide-in-from-right-2 duration-300">
                          <div className="space-y-6">
                              {renderLayoutSelector('et')}
                              {renderBaseFrequency()}
